    // [FAQ Items - Guest]
    q_g_booking_1: "I can't see the date I want.",
    a_g_booking_1: "Locally hosts are locals with main jobs, so schedules may vary. If you don't see a date, message the host! They might be able to adjust their schedule for you.",
    q_g_booking_2: "Is a private tour available?",
    a_g_booking_2: "Yes! Select the 'Private Tour' option when booking. If not available, message the host. They can prepare a customized experience just for you.",
    q_g_booking_3: "What is the 'Guaranteed Departure for 1 Person' option?",
    a_g_booking_3: "Tours usually require 2+ people. This option guarantees departure for solo travelers for an extra fee. If others join later, the extra fee is 100% refunded.",
    q_g_booking_4: "What payment methods are supported?",
    a_g_booking_4: "We support credit/debit cards (Visa, Master) and simple payments like KakaoPay. More methods coming soon.",
    q_g_booking_5: "Can I pay separately from my group?",
    a_g_booking_5: "Yes. Book separately for the same time slot, then message the host saying 'We are a group'.",

    q_g_exp_1: "I don't speak the language. Can I join?",
    a_g_exp_1: "Don't worry! You can enjoy the tour without language barriers. All communication with Locally hosts is supported in your language.",
    q_g_exp_2: "How do I contact the host?",
    a_g_exp_2: "Once booked, a 1:1 chat opens in the 'Messages' tab. Feel free to ask about meeting points, preparations, etc.",
    q_g_exp_3: "What if I'm late?",
    a_g_exp_3: "Tours start on time. Late arrival may result in being unable to join (considered a same-day cancellation, no refund). Please contact the host in advance if you're running late.",
    q_g_exp_4: "Are meals/drinks included?",
    a_g_exp_4: "Most tours don't include meal costs. You can pay for your own orders or split the bill with the host at the end. Check 'Included' details before booking.",
    q_g_exp_5: "Can I take photos?",
    a_g_exp_5: "Yes! Ask the host for a photo. However, please follow guidelines in restricted areas (e.g., museums) and respect others' privacy.",
    q_g_exp_6: "Can seniors or children join?",
    a_g_exp_6: "Everyone is welcome! However, some tours (walking-heavy, alcohol) may have restrictions. Message the host in advance to check or request adjustments.",
    q_g_exp_7: "Restrooms or breaks during the tour?",
    a_g_exp_7: "Locally tours are flexible. Tell the host anytime if you need a break or a restroom. They know the best spots.",

    q_g_cancel_1: "What if I'm late on the day?",
    a_g_cancel_1: "Tours start on time. Late arrival means no joining (no refund). Please arrive 10 mins early or contact the host ASAP.",
    q_g_cancel_2: "What if it rains?",
    a_g_cancel_2: "Light rain? The tour goes on! In severe weather (typhoon, etc.), the host may cancel for safety. In this case, you get a 100% refund.",
    q_g_cancel_3: "Refund policy?",
    a_g_cancel_3: "20 days before: 100%, 7 days: 70%, 1 day: 40%. Same-day cancellation: No refund. Host cancellation: 100% refund.",
    q_g_cancel_4: "When do I get my refund?",
    a_g_cancel_4: "Refund processing starts immediately upon approval. It may take 3-5 business days depending on your card issuer.",
    q_g_cancel_5: "Can I change the date?",
    a_g_cancel_5: "Date changes aren't possible after confirmation. Please cancel and re-book. Cancellation fees may apply.",

    q_g_account_1: "Is the host reliable?",
    a_g_account_1: "All Locally hosts undergo strict identity verification. Plus, their reputation is transparently managed via reviews from real guests.",
    q_g_account_2: "I forgot my password.",
    a_g_account_2: "Click 'Forgot Password' on the login screen to reset it via email.",
    q_g_account_3: "How do I delete my account?",
    a_g_account_3: "Go to Account Settings > Delete Account. All data and coupons will be permanently deleted.",

    // [FAQ Items - Host]
    q_h_start_1: "Requirements to be a host?",
    a_h_start_1: "No license needed! Any local wanting to share their lifestyle is welcome. Your daily life (shopping, hiking) can be a special trip for someone.",
    q_h_start_2: "Is there a registration fee?",
    a_h_start_2: "No, it's free. A small commission fee applies only when a booking is confirmed and you earn revenue.",
    q_h_start_3: "How much is the commission?",
    a_h_start_3: "Locally's platform fee is 20%. This covers payment fees, server costs, marketing, tax, etc.",
    q_h_start_4: "How much can I earn?",
    a_h_start_4: "You set the price. Popular hosts earn significant side income. You get paid the amount minus the 20% fee.",
    q_h_start_5: "Must I speak a foreign language?",
    a_h_start_5: "Required for foreign guests, but Korean is enough for Korean guests. Kindness and local knowledge matter more.",
    q_h_start_6: "What kind of tours can I make?",
    a_h_start_6: "Food tours, walks, hiking, cooking, photography... anything local! It doesn't have to be grand. Share 'real' local experiences.",
    q_h_start_7: "Must I use my own photo?",
    a_h_start_7: "Yes. A clear photo of your smiling face builds trust and increases booking rates.",
    q_h_start_8: "When do I get paid?",
    a_h_start_8: "Payouts are made 4 weeks after the tour date to your registered account.",
    q_h_start_9: "Can I host if I live abroad?",
    a_h_start_9: "Yes! You can host anywhere. For payouts, you may need PayPal, Line Pay, or Wise.",

    q_h_oper_1: "How to manage schedules?",
    a_h_oper_1: "Open only the dates/times you're available on the dashboard. You can block dates anytime.",
    q_h_oper_2: "How to set min. participants?",
    a_h_oper_2: "You can set a 'Guaranteed Departure Price for 1 Person' when registering a tour.",
    q_h_oper_3: "How to contact guests?",
    a_h_oper_3: "Use the in-app 1:1 chat safely without revealing personal contacts.",
    q_h_oper_4: "What if a guest is a No-Show?",
    a_h_oper_4: "Don't worry. You will still receive the payout according to the policy since payment is completed upon booking.",
    q_h_oper_5: "How to handle rude guests?",
    a_h_oper_5: "Report them immediately to support. We will verify facts and restrict their usage to protect you.",
