    // [FAQ Categories]
    faq_cat_booking: "预订与支付",
    faq_cat_experience: "体验之旅",
    faq_cat_cancellation: "取消与退款",
    faq_cat_account: "账号管理",
    faq_cat_start: "成为房东",
    faq_cat_operation: "运营秘籍",

    // [FAQ Items - Guest]
    // 预订
    q_g_booking_1: "找不到想要的日期。",
    a_g_booking_1: "Locally 的房东并非职业导游，而是拥有本职工作的当地人，因此日程可能会有所变动。如果日历上没有您想要的日期，请点击“联系房东”发送消息！房东可能会确认日程并为您协调时间。",
    q_g_booking_2: "可以预订私人（包团）游吗？",
    a_g_booking_2: "当然可以。预订时请选择“私人游”选项。（如果没有该选项，请私信咨询房东）房东将为您准备专属的定制体验。",
    q_g_booking_3: "什么是“单人成团”选项？",
    a_g_booking_3: "通常情况下需 2 人以上方可成团，但我们为独自旅行的游客提供“单人成团”选项。支付额外费用后即可确保出发，无需担心人数不足。如果后续有其他游客加入，您支付的额外费用将全额退还。",
    q_g_booking_4: "支持哪些支付方式？",
    a_g_booking_4: "目前支持韩国国内信用卡/借记卡、KakaoPay、NaverPay 等快捷支付。海外发行的卡支持 Visa、Master 卡，后续将引入更多支付方式。",
    q_g_booking_5: "可以和同伴分开支付吗？",
    a_g_booking_5: "可以。请各自预订，并选择相同的时间段。预订后请给房东留言“我们是同行者”，以便房东提前做好准备。",

    // 体验
    q_g_exp_1: "不会外语可以参加吗？",
    a_g_exp_1: "别担心！您可以毫无语言障碍地愉快享受。Locally 房东与您的所有沟通都将以您的语言进行，请放心。",
    q_g_exp_2: "如何联系房东？",
    a_g_exp_2: "预订确认后，“消息”标签页中会开启与房东的 1:1 聊天室。集合地点、准备物品、时间等任何疑问都可以自由咨询。",
    q_g_exp_3: "如果在旅游当天迟到怎么办？",
    a_g_exp_3: "行程将按预定时间出发，迟到可能导致无法参加，且将被视为当日取消，无法退款。如果您可能会迟到，请务必提前联系房东。",
    q_g_exp_4: "费用包含餐费或饮料吗？",
    a_g_exp_4: "大多数行程不包含餐费。通常是在探访当地美食店时各自支付点餐费用，或者由房东先支付，行程结束后再进行结算（AA制）。预订前请务必确认“包含项目”。",
    q_g_exp_5: "可以拍照吗？",
    a_g_exp_5: "可以自由拍照！还可以请房东帮您拍人生美照。但在美术馆内部或特定商店等限制拍摄的区域，请听从房东的指引，并请注意保护他人的肖像权。",
    q_g_exp_6: "老人或孩子可以参加吗？",
    a_g_exp_6: "是的，无论男女老少都欢迎。但步行较多或涉及饮酒的行程可能会有限制。如果有同伴，请提前给房东发消息。房东可以调整为轻松的步行路线或为孩子准备特别关照。",
    q_g_exp_7: "行程中如何上洗手间或休息？",
    a_g_exp_7: "Locally 的行程不像跟团游那样紧凑。走累了或想上洗手间，随时告诉房东。房东知道当地只有当地人知道的干净洗手间位置，或者氛围很好的休息长椅。",

    // 取消与退款
    q_g_cancel_1: "如果当天迟到怎么办？",
    a_g_cancel_1: "行程按时出发，迟到可能无法参加。（视为当日取消/不可退款）建议提前 10 分钟到达。如果预计会迟到，请务必立即联系房东。",
    q_g_cancel_2: "下雨天行程会照常进行吗？",
    a_g_cancel_2: "小雨将作为浪漫的雨中漫步照常进行。但台风等由于恶劣天气存在安全隐患时，房东可能会决定取消，此时将免手续费 100% 全额退款。",
    q_g_cancel_3: "退款规定是怎样的？",
    a_g_cancel_3: "出发日前 20 天退 100%，7 天前退 70%，1 天前退 40%，当天取消不可退款。若因房东原因取消，无论何时均全额退款。",
    q_g_cancel_4: "取消预订后何时退款？",
    a_g_cancel_4: "取消申请经系统处理完成后，会立即向发卡行发送取消请求。根据发卡行的不同，可能需要 3~5 个工作日。借记卡通常在 2 天内入账。",
    q_g_cancel_5: "可以更改日期吗？",
    a_g_cancel_5: "预订确认后原则上不可更改日期，需取消原预订后重新预订。此时可能会根据原预订的取消时间产生退款手续费，请注意。",

    // 账号管理
    q_g_account_1: "房东值得信任吗？",
    a_g_account_1: "Locally 的所有房东都经过严格的身份认证（本人确认、手机号认证、账户认证）。此外，通过实际参与行程的游客的真实评价，透明地管理声誉，请放心预订。",
    q_g_account_2: "忘记了密码。",
    a_g_account_2: "点击登录屏幕下方的“找回密码”，通过邮箱验证后即可重新设置。",
    q_g_account_3: "如何注销会员？",
    a_g_account_3: "可在 我的页面 > 账号设置 底部进行注销。注销时所有旅行记录和优惠券将消失，且无法恢复。",

    // [FAQ Items - Host]
    // 成为房东
    q_h_start_1: "注册房东有什么条件？",
    a_h_start_1: "无需资格证！只要居住在当地，愿意分享自己的喜好和故事，任何人都欢迎。探店、散步、购物等，您的日常生活对别人来说可能就是一次特别的旅行。",
    q_h_start_2: "需要注册费吗？",
    a_h_start_2: "不需要，注册房东及发布行程全额免费。只有预订确认产生收益时，才会收取规定的手续费。",
    q_h_start_3: "手续费是多少？",
    a_h_start_3: "Locally 的平台手续费为预订金额的 20%。该费用包含支付代理费、服务器维护费、营销费、税金及附加费用等。",
    q_h_start_4: "收益有多少？",
    a_h_start_4: "行程费用由房东亲自设定。人气房东每月可获得数百万韩元的副业收入。扣除 Locally 手续费 (20%) 后的金额将进行结算。",
    q_h_start_5: "必须精通外语吗？",
    a_h_start_5: "如果是针对外国游客的行程，必须会外语；但如果是针对韩国游客，只会韩语也足够。相比语言能力，亲切感和当地知识更重要。",
    q_h_start_6: "可以制作什么样的行程？",
    a_h_start_6: "探店、胡同散步、登山、烹饪课、摄影等，所有在当地能进行的活动都可以。不需要很宏大。请分享只有当地人知道的“真实”体验。",
    q_h_start_7: "头像必须是本人吗？",
    a_h_start_7: "是的，为了给游客信任感，建议使用能看清面部的本人照片。相比风景或动物照片，房东灿烂的笑容有助于提高预订率。",
    q_h_start_8: "什么时候结算？",
    a_h_start_8: "以行程完成日期为准，4 周后统一汇入您注册的账户。（如遇节假日，则顺延至下一个工作日发放）",
    q_h_start_9: "居住在海外也可以注册吗？",
    a_h_start_9: "是的，无论身在世界何处，都可以作为 Locally 房东开展活动。如需通过海外账户接收结算，可能需要关联 PayPal、Line Pay 或 Wise。",

    // 运营秘籍
    q_h_oper_1: "如何管理日程？",
    a_h_oper_1: "在房东仪表板中，只需开启可用的日期和时间即可。本职工作忙碌时，可以随时屏蔽预订，活动非常灵活。",
    q_h_oper_2: "如何设定最少出发人数？",
    a_h_oper_2: "发布商品时可以设定“单人成团金额”。",
    q_h_oper_3: "如何联系游客？",
    a_h_oper_3: "无需通过个人联系方式，通过 Locally App 内的“1:1 消息”功能安全沟通。预订确认前也能收到咨询消息。",
    q_h_oper_4: "如果游客未出现(No-Show)怎么办？",
    a_h_oper_4: "别担心。预订确认时已完成支付，即使游客未出现，也会按照规定向您支付结算金。",
    q_h_oper_5: "如何应对无理取闹的游客？",
    a_h_oper_5: "如果行程中遇到无礼或威胁安全的游客，请立即向 Locally 客服中心举报。确认事实后，我们将采取限制该游客使用的措施，尽全力保护房东。",
