type LanguageContextValue = {
  lang: Locale;
  setLang: (newLang: Locale) => void;
  t: (key: string, vars?: Record<string, string | number>) => string;
};

const LanguageContext = createContext<LanguageContextValue | null>(null);

const interpolate = (template: string, vars?: Record<string, string | number>) => {
  if (!vars) return template;
  return template.replace(/\{(\w+)\}/g, (_, token: string) => {
    const value = vars[token];
    return value === undefined || value === null ? `{${token}}` : String(value);
  });
};

export function LanguageProvider({
  children,
  initialLocale = 'ko',
}: {
  children: React.ReactNode;
  initialLocale?: Locale;
}) {
  const pathname = usePathname();
  const [lang, setLang] = useState<Locale>(initialLocale);

  useEffect(() => {
    const path = window.location.pathname || pathname || '/';
    const pathLang = (path.split('/')[1] || '').toLowerCase();
    let resolved: Locale = initialLocale;

    // 1) URL 언어 프리픽스가 있으면 최우선 사용
    if (isSupportedLocale(pathLang)) {
      resolved = pathLang;
    } else {
      // 2) 저장된 사용자 선택값(localStorage)이 있으면 유지
      const saved = (localStorage.getItem(APP_LANG_KEY) || '').toLowerCase();
      if (isSupportedLocale(saved) && dictionary[saved]) {
        resolved = saved;
      } else {
        // 3) 첫 방문(저장값 없음)만 브라우저 언어로 1회 추론
        resolved = initialLocale || detectLocaleFromNavigator();
      }
    }

    // eslint-disable-next-line react-hooks/set-state-in-effect
    setLang(resolved);
    persistLocale(resolved);
  }, [initialLocale, pathname]);

  const changeLang = (newLang: Locale) => {
    setLang(newLang);
    persistLocale(newLang);
  };

  const t = (key: string, vars?: Record<string, string | number>) => {
    const template = dictionary[lang]?.[key] ?? experienceUiDictionary[lang]?.[key] ?? key;
    return interpolate(template, vars);
  };

  return (
    <LanguageContext.Provider value={{ lang, setLang: changeLang, t }}>
      {children}
    </LanguageContext.Provider>
  );
}

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguage must be used within LanguageProvider');
  }
  return context;
};
